.d-hardware-led-display{height:320px;min-height:320px;width:100%;position:relative;overflow:hidden;box-sizing:border-box;display:grid;place-items:center;background:#eeefed;color:#373b3d;font:400 12px/1.4 Inter,Arial,sans-serif;font-variant-numeric:tabular-nums}.d-hardware-led-display *{box-sizing:border-box}.d-hardware-led-display button,.d-hardware-led-display input{font:inherit}.d-hardware-led-display button{cursor:pointer;touch-action:manipulation}.d-hardware-led-display button:focus-visible,.d-hardware-led-display input:focus-visible,.d-hardware-led-display [tabindex]:focus-visible{outline:2px solid #5e8097;outline-offset:5px}.d-hardware-led-display button:disabled{cursor:wait}.d-hardware-led-display-sr{position:absolute;width:1px;height:1px;overflow:hidden;clip-path:inset(50%)}.d-hardware-led-display-caption{position:absolute;bottom:22px;left:12px;right:12px;text-align:center;color:#727677;font-size:11px}.d-hardware-led-display-actions{display:flex;align-items:center;justify-content:center;gap:18px;position:absolute;bottom:23px;left:15px;right:15px}.d-hardware-led-display-actions button{border:0;border-bottom:1px solid #b5baba;background:none;color:#535b5f;padding:3px 0;font-size:11px}.d-hardware-led-display svg{display:block}.d-hardware-led-display button svg{pointer-events:none}@media(prefers-reduced-motion:reduce){.d-hardware-led-display *,.d-hardware-led-display *:before,.d-hardware-led-display *:after{animation:none!important;transition:none!important;scroll-behavior:auto!important}}
.d-hardware-led-display{background:#e9eae7}.d-hardware-led-display-clock{width:258px;height:132px;margin-top:-12px;padding:18px 16px 10px;border-radius:18px 18px 13px 13px;background:linear-gradient(175deg,#3d4042,#303335 80%);box-shadow:inset 0 1px 1px #ffffff32,inset 0 -3px 1px #151819,0 3px 3px #0002,0 14px 24px -10px #26303369;position:relative}.d-hardware-led-display-clock:before,.d-hardware-led-display-clock:after{content:'';position:absolute;bottom:-4px;height:5px;width:30px;border-radius:0 0 3px 3px;background:#25282a}.d-hardware-led-display-clock:before{left:25px}.d-hardware-led-display-clock:after{right:25px}.d-hardware-led-display-lens{height:75px;border-radius:8px;padding:13px 12px;background:linear-gradient(168deg,#191d1d,#171a1a);box-shadow:0 1px #ffffff18,inset 0 1px 5px #0008;border:1px solid #121616}.d-hardware-led-display-lens svg{width:100%;height:100%}.d-hardware-led-display-bottom{display:flex;align-items:center;justify-content:space-between;margin-top:10px;color:#9c9e9c;font-size:8px;letter-spacing:.07em}.d-hardware-led-display-bottom>div{display:flex;gap:11px;align-items:center}.d-hardware-led-display-bottom button{padding:0;border:0;background:none;color:#b3b9b8;font-size:9px;min-width:17px}.d-hardware-led-display-lens circle{transition:fill .15s}.d-hardware-led-display[data-power=off] .d-hardware-led-display-lens{opacity:.75}
.d-hardware-led-display-bottom{margin-top:6px}.d-hardware-led-display-bottom>div{gap:5px}.d-hardware-led-display-bottom button{min-width:24px;height:24px;padding:0;display:grid;place-items:center;line-height:1}.d-hardware-led-display-bottom button[data-format]{min-width:28px}
